//! Protected acceptance: cutover `preconditions` caps whole-file reads.
//!
//! Test Author-owned suite: do not edit this file to make it pass. Implement
//! the cap in `crates/cutover/src/bin/preconditions.rs` instead.
//!
//! Contract under test (matches the capped siblings `ghost_cleanup` and
//! `raid-remove`, which refuse with `<role> exceeds 8 MiB`):
//!
//! * Every file the checker buffers is capped at 8 MiB: the parity doc, the
//!   cutover doc, each timer unit, and the registry fixture.
//! * A file over the cap is refused as a failed check (exit 1): the JSON
//!   report carries `ok: false`, one `missing` entry names the file role
//!   (its repo-relative path) and the `8 MiB` cap, and stderr names that
//!   same entry, mirroring the existing missing-item behavior.
//! * A file at exactly the cap is accepted: the boundary is strict `>`.
//! * Valid runs are byte-identical to today: exit 0, `ok: true`, no missing
//!   items, empty stderr.
//!
//! Offline fixtures only: synthetic over/at-cap files under a scratch copy
//! of the checked-in tree. No DB, no network, no writes outside temp dirs.

use std::fs;
use std::path::{Path, PathBuf};
use std::process::{Command, Output};

/// The pinned cap: 8 MiB, matching the capped cutover siblings. Kept as a
/// literal here so the contract does not move with the implementation.
const CAP_BYTES: usize = 8 * 1024 * 1024;
/// Fixed refusal vocabulary: the cap is always named as `8 MiB`.
const CAP_WORD: &str = "8 MiB";

const PARITY_DOC: &str = "docs/parity.md";
const PARITY_MARKER: &str = "Unmapped: **0**";
const CUTOVER_DOC: &str = "docs/cutover.md";
const TIMER_UNIT: &str = "deploy/two-bot-next-backup.timer";
const REGISTRY_FIXTURE: &str = "crates/core/tests/fixtures/legacy_registry.json";

const REQUIRED_SECTIONS: &[&str] = &[
    "## Roles, safety and evidence",
    "## Preconditions: all must pass",
    "## T-minus checklist",
    "## Freeze and drain (T_f)",
    "## Tool availability and command sheet",
    "## Data copy and verification",
    "## Registry swap, first boot and go/no-go",
    "## 48-hour watch",
    "## Rollback: preserve Next-window writes before reopening legacy",
    "## Communication template",
];

fn run(args: &[&str]) -> Output {
    Command::new(env!("CARGO_BIN_EXE_preconditions"))
        .env_clear()
        .args(args)
        .output()
        .unwrap()
}

fn workspace_root() -> PathBuf {
    let manifest = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    manifest
        .parent()
        .and_then(|p| p.parent())
        .unwrap()
        .to_owned()
}

fn copy_tree(src: &Path, dst: &Path, rel: &str) {
    let from = src.join(rel);
    let to = dst.join(rel);
    if from.is_dir() {
        fs::create_dir_all(&to).unwrap();
        for entry in fs::read_dir(&from).unwrap() {
            let entry = entry.unwrap();
            let name = entry.file_name().to_string_lossy().into_owned();
            copy_tree(src, dst, &format!("{rel}/{name}"));
        }
    } else {
        fs::create_dir_all(to.parent().unwrap()).unwrap();
        fs::copy(&from, &to).unwrap();
    }
}

fn scratch_base() -> PathBuf {
    std::env::var_os("PAPERCLIP_RUN_SCRATCH_DIR")
        .map(PathBuf::from)
        .or_else(|| std::env::var_os("PAPERCLIP_SCRATCH_DIR").map(PathBuf::from))
        .unwrap_or_else(std::env::temp_dir)
}

fn time_nanos() -> u128 {
    std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap()
        .as_nanos()
}

fn scratch_tree(name: &str, mutate: impl FnOnce(&Path)) -> PathBuf {
    let root = workspace_root();
    let dir = scratch_base().join(format!(
        "preconditions-cap-{name}-{}-{}",
        std::process::id(),
        time_nanos()
    ));
    for rel in [
        "docs/parity.md",
        "docs/cutover.md",
        "docs/staging-soak.md",
        "docs/backup.md",
        "docs/preflight.md",
        "docs/commands.md",
        "docs/runbook.md",
        "deploy/two-bot-next-backup.timer",
        "deploy/two-bot-next-guild-config-backup.timer",
        "deploy/two-bot-next-restore-drill.timer",
        "crates/core/tests/fixtures/legacy_registry.json",
    ] {
        copy_tree(&root, &dir, rel);
    }
    mutate(&dir);
    dir
}

fn report(stdout: &[u8]) -> serde_json::Value {
    serde_json::from_slice(stdout).unwrap()
}

/// Pad `head` with filler to exactly `total` bytes.
fn sized(head: &str, total: usize) -> String {
    assert!(
        head.len() < total,
        "fixture head ({} bytes) must fit under {total} bytes",
        head.len()
    );
    let mut out = String::with_capacity(total);
    out.push_str(head);
    out.push_str(&"x".repeat(total - head.len()));
    debug_assert_eq!(out.len(), total);
    out
}

fn missing_list(value: &serde_json::Value) -> Vec<String> {
    value["missing"]
        .as_array()
        .unwrap()
        .iter()
        .map(|m| m.as_str().unwrap().to_owned())
        .collect()
}

/// Over-cap contract: exit 1, `ok: false`, one missing entry naming the file
/// role and the cap, and stderr naming that same entry.
fn assert_refused(output: &Output, role: &str) {
    assert_eq!(
        output.status.code(),
        Some(1),
        "over-cap {role} must fail as a missing item, not usage or success"
    );
    let value = report(&output.stdout);
    assert_eq!(value["ok"], false);
    let missing = missing_list(&value);
    let entry = missing
        .iter()
        .find(|m| m.contains(role) && m.contains(CAP_WORD));
    assert!(
        entry.is_some(),
        "missing must name the {role} role and the {CAP_WORD} cap, got: {missing:?}"
    );
    let stderr = String::from_utf8(output.stderr.clone()).unwrap();
    assert!(
        stderr.contains(entry.unwrap()),
        "stderr must name the refused entry, got: {stderr:?}"
    );
}

/// At-cap and valid contract: fully accepted, byte-identical to today.
fn assert_accepted(output: &Output) {
    assert_eq!(output.status.code(), Some(0));
    let value = report(&output.stdout);
    assert_eq!(value["ok"], true);
    assert!(value["missing"].as_array().unwrap().is_empty());
    assert!(output.stderr.is_empty());
}

/// Control: an untouched scratch tree passes, so a refusal below is
/// attributable to the cap and not to the scratch harness.
#[test]
fn valid_scratch_tree_passes() {
    let dir = scratch_tree("control", |_| {});
    let arg = dir.to_string_lossy().into_owned();
    let output = run(&["--repo-root", &arg]);
    assert_accepted(&output);
    let value = report(&output.stdout);
    let names: Vec<&str> = value["checks"]
        .as_array()
        .unwrap()
        .iter()
        .map(|c| c["name"].as_str().unwrap())
        .collect();
    assert_eq!(
        names,
        vec![
            "parity-zero-unmapped",
            "runbook-docs",
            "runbook-sections",
            "timer-units",
            "registry-fixture",
        ]
    );
    fs::remove_dir_all(&dir).ok();
}

#[test]
fn over_cap_parity_doc_is_refused_naming_role_and_cap() {
    let dir = scratch_tree("parity-over", |root| {
        // Marker present, so only the cap can refuse this file.
        let head = format!("{PARITY_MARKER}\n");
        fs::write(root.join(PARITY_DOC), sized(&head, CAP_BYTES + 1)).unwrap();
    });
    let arg = dir.to_string_lossy().into_owned();
    let output = run(&["--repo-root", &arg]);
    assert_refused(&output, PARITY_DOC);
    fs::remove_dir_all(&dir).ok();
}

#[test]
fn over_cap_cutover_doc_is_refused_naming_role_and_cap() {
    let dir = scratch_tree("cutover-over", |root| {
        // Every required section present, so only the cap can refuse it.
        let head = REQUIRED_SECTIONS.join("\n") + "\n";
        fs::write(root.join(CUTOVER_DOC), sized(&head, CAP_BYTES + 1)).unwrap();
    });
    let arg = dir.to_string_lossy().into_owned();
    let output = run(&["--repo-root", &arg]);
    assert_refused(&output, CUTOVER_DOC);
    fs::remove_dir_all(&dir).ok();
}

#[test]
fn over_cap_timer_unit_is_refused_naming_role_and_cap() {
    let dir = scratch_tree("timer-over", |root| {
        // Valid schedule present, so only the cap can refuse it.
        let head = "[Unit]\nDescription=cap fixture\n[Timer]\nOnCalendar=daily\n";
        fs::write(root.join(TIMER_UNIT), sized(head, CAP_BYTES + 1)).unwrap();
    });
    let arg = dir.to_string_lossy().into_owned();
    let output = run(&["--repo-root", &arg]);
    assert_refused(&output, TIMER_UNIT);
    fs::remove_dir_all(&dir).ok();
}

#[test]
fn over_cap_registry_fixture_is_refused_naming_role_and_cap() {
    let dir = scratch_tree("registry-over", |root| {
        // Valid JSON with a non-empty commands array, so only the cap
        // can refuse it (and the refusal must name the cap, not JSON).
        let prefix = r#"{"commands": [{"id": "cmd", "pad": ""#;
        let suffix = r#""}]}"#;
        let pad_len = (CAP_BYTES + 1)
            .checked_sub(prefix.len() + suffix.len())
            .unwrap();
        let content = format!("{prefix}{}{suffix}", "x".repeat(pad_len));
        assert_eq!(content.len(), CAP_BYTES + 1);
        let parsed: serde_json::Value = serde_json::from_str(&content).unwrap();
        assert!(!parsed["commands"].as_array().unwrap().is_empty());
        fs::write(root.join(REGISTRY_FIXTURE), content).unwrap();
    });
    let arg = dir.to_string_lossy().into_owned();
    let output = run(&["--repo-root", &arg]);
    assert_refused(&output, REGISTRY_FIXTURE);
    fs::remove_dir_all(&dir).ok();
}

#[test]
fn at_cap_parity_doc_is_accepted() {
    let dir = scratch_tree("parity-at", |root| {
        let head = format!("{PARITY_MARKER}\n");
        fs::write(root.join(PARITY_DOC), sized(&head, CAP_BYTES)).unwrap();
    });
    let arg = dir.to_string_lossy().into_owned();
    assert_accepted(&run(&["--repo-root", &arg]));
    fs::remove_dir_all(&dir).ok();
}

